/* Video und Standbild in einer Anfrage, wie die Oberflaeche sie schickt. */
function sendVideo(itemId, { video = MP4(), name = 'clip.mp4', type = 'video/mp4',
                              stillFrame = Buffer.from(PNG_BASE64, 'base64'),
                              stillFrameName = 'stillframe.jpg', stillFrameType = 'image/jpeg',
                              duration = 42, withoutStillFrame = false } = {}) {
  const files = [{ field: 'video', name, type, content: video }];
  if (!withoutStillFrame)
    files.push({ field: 'stillFrame', name: stillFrameName, type: stillFrameType, content: stillFrame });
  return sendMultipart(`/api/items/${itemId}/videos`, 'video', files,
                         duration === null ? {} : { duration: String(duration) });
}

async function putPhotoAn(itemId) {
  const response = await sendMultipart(`/api/items/${itemId}/photos`, 'photos',
    [{ name: 'p.png', type: 'image/png', content: Buffer.from(PNG_BASE64, 'base64') }]);
  return response.content.photos[0];
}

// Multipart, weil Bilder mitkommen koennen.
async function sendComment(itemId, fields, images = []) {
  return sendMultipart(`/api/items/${itemId}/comments`, 'images', images, fields);
}

const sendFiles = (itemId, files) =>
  sendMultipart(`/api/items/${itemId}/attachments`, 'files', files);

// Von Hand, ohne weitere Bibliothek. Buffer nicht ueber Strings fuehren,
// sonst zerfaellt jedes Byte ueber 127.
async function sendMultipart(filePath, field, files, fields = {}) {
  const limit = '----pruefung' + crypto.randomBytes(6).toString('hex');
  const parts = [];
  for (const [k, v] of Object.entries(fields)) {
    parts.push(Buffer.from(
      `--${limit}\r\nContent-Disposition: form-data; name="${k}"\r\n\r\n${v}\r\n`, 'utf8'));
  }
  for (const d of files) {
    const content = Buffer.isBuffer(d.content) ? d.content : Buffer.from(d.content, 'utf8');
    // d.field: der Videoweg schickt zwei Felder in einer Anfrage.
    parts.push(Buffer.from(
      `--${limit}\r\nContent-Disposition: form-data; name="${d.field || field}"; filename="${d.name}"\r\n` +
      `Content-Type: ${d.type}\r\n\r\n`, 'utf8'));
    parts.push(content);
    parts.push(Buffer.from('\r\n', 'utf8'));
  }
  parts.push(Buffer.from(`--${limit}--\r\n`, 'utf8'));
  const a = await fetch(BASE + filePath, {
    method: 'POST',
    headers: { ...H.withCsrf(H.cookie), 'content-type': `multipart/form-data; boundary=${limit}` },
    body: Buffer.concat(parts)
  });
  return { status: a.status, content: await a.json().catch(() => null) };
}

// Echte .docx: ZIP mit word/document.xml, ungepackt gespeichert.
function buildDocx(text) {
  const paragraphs = text.split('\n').map(z =>
    `<w:p><w:r><w:t>${z.replace(/&/g, '&amp;').replace(/</g, '&lt;')}</w:t></w:r></w:p>`).join('');
  const xml = Buffer.from(`<?xml version="1.0"?><w:document xmlns:w="x"><w:body>${paragraphs}</w:body></w:document>`, 'utf8');
  const name = Buffer.from('word/document.xml', 'utf8');
  const crc = crc32(xml);

  const local = Buffer.alloc(30);
  local.writeUInt32LE(0x04034b50, 0); local.writeUInt16LE(20, 4);
  local.writeUInt16LE(0, 8);                       // Methode 0 = ungepackt
  local.writeUInt32LE(crc, 14);
  local.writeUInt32LE(xml.length, 18); local.writeUInt32LE(xml.length, 22);
  local.writeUInt16LE(name.length, 26);
  const file = Buffer.concat([local, name, xml]);

  const central = Buffer.alloc(46);
  central.writeUInt32LE(0x02014b50, 0); central.writeUInt16LE(20, 4); central.writeUInt16LE(20, 6);
  central.writeUInt16LE(0, 10);
  central.writeUInt32LE(crc, 16);
  central.writeUInt32LE(xml.length, 20); central.writeUInt32LE(xml.length, 24);
  central.writeUInt16LE(name.length, 28);
  central.writeUInt32LE(0, 42);                    // Versatz des oertlichen Kopfes
  const directory = Buffer.concat([central, name]);

  const endRecord = Buffer.alloc(22);
  endRecord.writeUInt32LE(0x06054b50, 0);
  endRecord.writeUInt16LE(1, 8); endRecord.writeUInt16LE(1, 10);
  endRecord.writeUInt32LE(directory.length, 12);
  endRecord.writeUInt32LE(file.length, 16);
  return Buffer.concat([file, directory, endRecord]);
}

function crc32(buf) {
  let c, table = crc32.table;
  if (!table) {
    table = crc32.table = [];
    for (let n = 0; n < 256; n++) {
      c = n;
      for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      table[n] = c >>> 0;
    }
  }
  let r = 0xffffffff;
  for (const b of buf) r = table[(r ^ b) & 0xff] ^ (r >>> 8);
  return (r ^ 0xffffffff) >>> 0;
}

/* Roher fetch wegen Multipart, daher die Freigabe von Hand davor. */
async function sendImport(object, mode, withoutShare = false) {
  if (!withoutShare) await shareMain('import');
  const limit = '----pruefung' + crypto.randomBytes(6).toString('hex');
  const part = (name, value, fileName) =>
    `--${limit}\r\nContent-Disposition: form-data; name="${name}"` +
    (fileName ? `; filename="${fileName}"\r\nContent-Type: application/json` : '') +
    `\r\n\r\n${value}\r\n`;
  const body = part('mode', mode) + part('file', JSON.stringify(object), 'export.json') + `--${limit}--\r\n`;
  const a = await fetch(BASE + '/api/import', {
    method: 'POST',
    headers: { ...H.withCsrf(H.cookie), 'content-type': `multipart/form-data; boundary=${limit}` },
    body: body
  });
  return { status: a.status, content: await a.json().catch(() => null) };
}


