  await fCall('cookie-f-bert', 'PUT', `/api/items/${fIdea.id}`, { tested: true });
  const fAgainBert = await fCall('cookie-f-bert', 'PUT', `/api/items/${fIdea.id}/ratings`,
    { criterionId: fLookId, value: 4 });
  check('Und am getesteten Eintrag nimmt die Route wieder an',
    fAgainBert.status === 200 && fAgainBert.content?.avgRating === 4,
    `Status ${fAgainBert.status}, avgRating ${fAgainBert.content?.avgRating}`);
  await fCall('cookie-f-anna', 'DELETE', `/api/items/${fIdea.id}`);

